from pathlib import Path
import csv,json,re,html,hashlib,struct,datetime,zipfile
R=Path(__file__).resolve().parent
H=html.escape
now=datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='seconds')
def read(n):return (R/n).read_text(encoding='latin1').strip()
def savecsv(name,heads,rows):
 with (R/name).open('w',newline='',encoding='utf-8-sig') as f:
  w=csv.writer(f);w.writerow(heads);w.writerows(rows)
def tab(heads,rows,cls=''):
 return '<div class="table-wrap"><table class="'+cls+'"><thead><tr>'+''.join('<th>'+H(str(x))+'</th>' for x in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+H(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def pre(n):return '<pre>'+H(read(n))+'</pre>'
def link(url,label):return '<a href="'+H(url,quote=True)+'">'+H(label)+'</a>'
def p(s):return '<p>'+s+'</p>'
def details(title,body):return '<details><summary>'+H(title)+'</summary>'+body+'</details>'
sections=[]
def section(id,title,body):sections.append((id,title,'<section id="'+id+'"><h2>'+H(title)+'</h2>'+body+'</section>'))
native=[l.split('\t') for l in read('native.tsv').splitlines()]
loaded=[]
for a in native:
 if a[0] in ('LIB','DEV'):
  loaded.append([a[0],a[1],a[2]+'.'+a[3],a[4],'0x'+a[5],a[6],a[7],'0x'+a[8],a[9].strip() if len(a)>9 else ''])
savecsv('loaded-libraries-and-devices.csv',['Kind','Name','Header version','Open count','Base address','Negative bytes','Positive bytes','Flags','Embedded ID string'],loaded)
files=[]
for l in read('system-files.txt').splitlines():
 a=l.strip('*"').split('|')
 if len(a)==5:files.append(a)
assert len(files)==2763
savecsv('system-files.csv',['Path','Bytes','Filesystem date (Amiga clock)','Filesystem time','Protection'],files)
meta={r[0].lower():r for r in files}
versions=[]
for i in range(11):
 for block in read(f'versions-{i}.txt').split('@@')[1:]:
  a=block.strip().splitlines();path=a[0];v=' | '.join(a[1:]);m=meta.get(path.lower(),[path,'','','',''])
  versions.append([path,v,m[1],m[2],m[3],m[4]])
assert len(versions)==494
savecsv('installed-component-versions.csv',['Path','Version FILE FULL output','Bytes','Filesystem date (Amiga clock)','Filesystem time','Protection'],versions)
versionmap={r[0].lower():r[1] for r in versions}
ver=lambda name:versionmap.get(name.lower(),'Not queried')
libs=[r for r in loaded if r[0]=='LIB'];devs=[r for r in loaded if r[0]=='DEV']
resources=[a[1:] for a in native if a[0]=='RESOURCE']
fs=[l.split('\t') for l in read('filesystems.tsv').splitlines() if l.strip()]
savecsv('filesystem-resources.csv',['DOS type','Version','Priority','ID string'],fs)
