section('audio','Audio and MIDI configuration',tab(['Component','Installed / loaded version'],[['ahi.device',ver('SYS:Devs/ahi.device')],['AHI preferences',ver('SYS:Prefs/AHI')],['Paula output',ver('SYS:Devs/AHI/paula.audio')],['ZZ9000AX output',ver('SYS:Devs/AHI/ZZ9000AX.audio')],['File output',ver('SYS:Devs/AHI/filesave.audio')],['MHI ZZ9000',ver('SYS:Libs/MHI/mhizz9000.library')],['CAMD',ver('SYS:Libs/camd.library')],['MidiPorts preferences',ver('SYS:Prefs/MidiPorts')]])+p('Saved <code>ENVARC:Sys/ahi.prefs</code> settings, decoded using the '+link(source_urls['ahi'],'AHI preference structure')+' and the installed AudioModes definitions:')+tab(['Unit','Mode ID','Saved output mode','Frequency Hz','Channel field'],[['Music Unit (255)' if a['unit']==255 else str(a['unit']),a['mode'],a['mode_name'],a['frequency_hz'],a['channels']] for a in audioprefs])+p('These are <strong>saved preferences</strong>, not a claim about every application’s active mixer format. ScummVM’s AHI mixer task, ahi.device and paula.audio were loaded during the audit. The Music Unit selects ZZ9000AX, but software installation and a preference selection do not establish that the AX daughterboard is physically fitted or audible.')+p('The prior ScummVM setup enabled CAMD’s internal serial port and verified the in.0/out.0 clusters. ScummVM is configured for CAMD/native MT-32. The owner said the Roland is not connected; no MIDI notes were sent during this audit and no physical MT-32 response is claimed.'))
section('os','Operating system, libraries and dates',tab(['Layer','Reported version / date','Interpretation'],[['Kickstart','47.115','Live ROM/system version; owner identifies OS release as 3.2.3'],['Exec','47.13 (1 January 2025)','Loaded system kernel'],['Intuition','47.53 (27 November 2024)','Loaded ROM/system component'],['DOS','47.30','Loaded header; no ID date exposed'],['Disk version','47.2 (10 April 2021)','version.library on disk and in memory'],['Workbench library','47.33 (31 March 2021)','Loaded and installed older disk component'],['SetPatch','47.4 (4 August 2020)','Installed executable'],['68060.library','47.2 (6 July 2022)','Loaded CPU support'],['mmu.library','47.10 (26 August 2025)','Loaded MMU support'],['MUI','muimaster.library 19.35 (12 February 1997)','Loaded version'],['AmiSSL','amisslmaster 5.23 / amissl_v353 5.23 (17 September 2025)','Installed; not present in initial loaded-library snapshot'],['Icon library','51.4 header; ID 51.4.600 (TC020)','Third-party replacement; header and full build identifier differ']])+p('<strong>OS consistency finding:</strong> this machine combines 2024/2025 ROM components with 2021 Workbench/disk components. The owner’s “OS 3.2.3” label should therefore be recorded alongside the actual versions, rather than used to certify a complete matching disk update. A future comparison against the owner’s registered 3.2.3 installation media can establish which disk files need updating; this audit has not installed or replaced them.')+p('<strong>Clock finding:</strong> the Mac reported 7 October 2026; the Amiga Date command returned <code>Thursday 09-Oct-25 16:20:43</code>. Numerous files also retain 1980 or archive-era timestamps. An embedded $VER date describes a component build/release; a filesystem timestamp describes stored metadata. Neither establishes installation date, hardware manufacture date or the age of this particular machine. Dates are preserved in their original formats in the CSVs.')+p('The tables distinguish loaded header versions, embedded ID strings and <code>Version FILE FULL</code> results. For example, ZZ9000.card’s loaded header says 1.0 while its embedded/file version says 1.13. That does not mean the wrong card firmware is running.'))
section('graphics','Graphics, ARM firmware and previous tests',tab(['Item','Result / status'],[['Native display','AGA PAL; 50 Hz VBlank; E-clock 709,379 Hz (not CPU clock)'],['Workbench screen','1920 × 800 × 8 bits/pixel'],['ScummVM screen','320 × 200 × 8 bits/pixel; active during audit'],['RTG core','rtg.library 43.538; Picasso96API.library 2.455; emulation.library 41.525 (29 July 2023)'],['Monitor driver',ver('SYS:Devs/Monitors/ZZ9000')],['ZZ9000 card driver',ver('SYS:Libs/Picasso96/ZZ9000.card')],['Current firmware register','$0113 at ZZ9000 base $40000000'],['Installed firmware record','BOOT_XX19c.bin, XACP 1.7; previous update and reboot/handshake verified'],['Firmware SHA-256','2b6a4224d4645694ef4d186baae14a86c100f4ce9e15033262a814cc239e7305'],['Patch suffix caveat','Register $0113 identifies the 1.19 family; XX19c suffix comes from the recorded installed artifact, not fresh full-flash readback']])+p('Prior hardware tests recorded ZZBenchGUI 1.3 ARM Core1 execution and XACP dispatch, followed by owner-confirmed ZZQuake display. The protocol and firmware project is '+link(source_urls['xacp'],'XACP-ZZ9000')+'. These tests establish usable ARM execution through XACP; they do not establish source-level ARM debugging support.')+tab(['Prior ZZBench metric','68060','ARM Core1'],[['Integer MIPS','53.36','1061.77'],['Floating-point MWIPS','42.77','917.31']])+p('The earlier benchmark displayed ARM DDR read/write/copy as 0.0 MB/s; that subtest remains unresolved and is not presented as a valid memory-health or bandwidth result. No benchmark was rerun for this inventory.'))
apps=[['AmigaBridge','SD032G:amiga-bridge/amiga-bridge','150,204 bytes; build/version from prior records: 1.20','Live AMIGABRIDGE port and TCP connection; Version FILE found no standard tag'],['Bridge network watcher','C:bridge-netwatch; S:Start-Amiga-Bridge-Auto','Custom native helper; no standard version tag','Live SIXIES.BRIDGE.NETWATCH port/task; starts bridge when interface has an IP'],['Roadie','HDD50Gig:Roadie','1.3.9 (2021-12-20)','Live ROADIE port/task'],['ScummVM','HDD50Gig:Games/ScummVM','AGA 68060 package 2.5.1.40; executable identifies 2.5.1, built 4 September 2026','Running; CAMD/MT-32 configured; no games added by our installation'],['ZZQuake','HDD50Gig:Games/ZZQuake','1.0; shareware Quake data','Prior installed/owner-confirmed display; not running at snapshot'],['ZZBenchGUI','SD032G:Drivers/XACP/ZZBench/ZZBenchGUI_v1.3','1.3','Prior native 68k/ARM test results retained'],['ZZ9000 firmware payload','SD032G:Drivers/XACP/BOOT_XX19c.bin','XX19c / XACP 1.7','Staged artifact and previous installation record'],['ARexx','SYS:System/RexxMast; rexxsyslib.library','47.2 library (19 August 2019)','RexxMaster task and REXX/AREXX public ports present']]
section('services','Applications, startup and running services',tab(['Application/service','Location','Version','Evidence'],apps)+p('AmigaBridge originates from '+link(source_urls['bridge'],'geekychris/amiga_mcp')+' with workspace adaptations; the separate bridge-netwatch helper was built for this installation. The bridge’s uptime tool reported 18 minutes 33 seconds at the initial snapshot; source inspection shows this counts from bridge initialization, not system boot. The Mac-side dashboard is at localhost:55010 and the real Amiga listens on TCP 2345. Simulator/emulator results are not used as hardware evidence.')+p('Startup currently invokes Roadshow networking, Poseidon’s saved stack loader, RexxMast and the bridge network watcher. The watcher checks for an active interface/address and avoids duplicate bridge processes. Its previous controlled restart tests passed; a cold-boot or Roadie disconnect/reconnect test is not newly certified by this report.')+p('<strong>Confirmed stale startup entries:</strong> <code>S:User-Startup</code> runs <code>SYS:C/StikyRMB</code>, which is absent; <code>S:Startup-Sequence</code> runs <code>HDD50Gig:VisualPrefs</code>, which is absent. These lines may produce launch errors. Their intended replacements/paths should be checked before any edit.')+details('Public ports, tasks, assigns and WBStartup inventory',''.join('<pre>'+H(o['text'])+'</pre>' for o in json.loads((R/'live-overview.json').read_text()) if o['tool'] in ['amiga_list_tasks','amiga_list_ports','amiga_list_assigns'])+pre('wbstartup.txt')))
section('recommendations','Findings and recommendations',tab(['Priority','Finding','Recommended follow-up'],[['Review','Clock differs by almost a year','Set the correct date/time and check RTC persistence when convenient; confirm the Mac date too before changing either clock.'],['Review','Mixed ROM and Workbench/disk component generations','Compare installed disk files with the owner’s 3.2.3 update manifest before doing a coordinated update.'],['Review','Missing StikyRMB and VisualPrefs startup targets','Locate the intended programs and correct or remove stale startup entries after checking their purpose.'],['Observe','X-Surf cumulative overruns','Compare counters before/after a controlled transfer; investigate only if overruns continue to grow or performance suffers.'],['Confirm','AHI Music Unit selects ZZ9000AX','Confirm AX hardware/output exists before relying on that preference; current ScummVM path uses loaded Paula audio.'],['Document','CPU clock, board revisions and physical chip markings unknown','Record component labels/photos during a future powered-off inspection; no need to infer them from benchmark speed.'],['Reconcile','Earlier Fast RAM estimate was 284 MB','Use the live 624 MiB map for the system record, retaining attribution caveats for the two non-ZZ banks.'],['Retest later','ZZBench ARM DDR subtest showed zero','Treat its memory-bandwidth result as unvalidated; CPU/XACP execution was verified separately.']])+p('Positive observations: bridge connected, network interface up, ARexx running, AHI/Paula loaded, Freeway controller/root hub configured, and mounted persistent filesystems validated with zero reported errors. These are operational snapshots, not exhaustive hardware stress tests.'))
section('libraries','Complete loaded libraries, classes and devices',p(f'{len(libs)} library-list entries and {len(devs)} device-list entries captured directly from Exec. Open count 0 means the object is resident but currently unused; it is not an error. USB class-provided device entries can exist without attached hardware. The bridge overview initially saw 76 libraries; ShowConfig subsequently loaded boards.library, giving {len(libs)} in the native snapshot.')+'<label class="filter">Filter loaded entries <input type="search" data-filter="loaded-table" placeholder="e.g. 68060, USB, 2025"></label>'+tab(['Kind','Name','Header version','Opens','Base','Embedded ID / date'],[[*r[:5],r[8]] for r in loaded],'loaded-table')+p('CSV: '+link('loaded-libraries-and-devices.csv','Loaded libraries and devices')+'.')+details('Registered Exec resource names',tab(['Resource','Address'],resources)))
section('installed','Installed component versions and file dates',p('These 494 queries cover selected components in C:, L:, Libs, Classes, Devs, Prefs, System, Tools, Utilities, MUI and AmiSSL. Some data files have no version tag; this is recorded rather than treated as failure. This is not a complete executable/version scan of the games and application data volumes.')+'<label class="filter">Filter installed components <input type="search" data-filter="installed-table" placeholder="e.g. AmiSSL, 68060, fat95"></label>'+tab(['Path','Version FILE FULL / embedded date','Bytes','Filesystem date','Time','Protection'],versions,'installed-table')+p('CSV: '+link('installed-component-versions.csv','Installed component versions')+'. Full SYS: metadata listing: '+link('system-files.csv','2,763 system file records')+'. File timestamps are not trusted installation dates.'))
section('evidence','Evidence files and reproducibility',p('The companion ZIP includes this HTML report, CSV/JSON inventories, raw read-only query output and the native probe sources. It excludes Amiga OS binaries, game assets and third-party driver binaries. The report opens locally without network dependencies and includes filters for the large tables. Browser Print / Save as PDF can print the narrative and loaded-library inventory; the 494-row installed table is intentionally omitted from print and remains in HTML/CSV.')+tab(['Artifact','Purpose'],[['hardware-inventory.csv','Hardware identification with evidence and unknowns'],['expansion-boards.csv','Six AutoConfig entries and raw IDs'],['memory-map.csv','RAM ranges and allocation priorities'],['volumes.csv','Persistent volume capacity/usage and filesystems'],['loaded-libraries-and-devices.csv','Native Exec inventory and embedded ID strings'],['installed-component-versions.csv','494 Version FILE FULL results with file metadata'],['system-files.csv','2,763 files under SYS: with sizes/dates/protection'],['audio-preferences.json','Saved AHI unit settings'],['native.tsv / filesystems.tsv','Raw native probe results'],['live-overview.json','Timestamped bridge overview'],['inventory.c / filesystems.c','Read-only native probe source'],['report-data.json','Machine-readable summary'],['SHA256SUMS.txt','Checksums for bundled evidence']])+p('Collection limits: no full disk image or sector scan; no per-chip physical inspection; no raw flash/RDB checksum audit; no new ARexx execution/source-debugging test; no exhaustive executable inventory of HDD50Gig: or SD032G:. The inventory does not prove that every installed library is ABI-compatible or every hardware port works under load.'))
css='''
:root{color-scheme:light;--ink:#162330;--muted:#526779;--accent:#007d8a;--line:#d7e2e8;--bg:#f3f6f8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#122d3b;color:white;padding:48px max(5vw,24px) 36px}header .eyebrow{letter-spacing:.14em;text-transform:uppercase;color:#89dce1;font-size:12px}h1{font-size:44px;line-height:1.1;margin:12px 0}header p{max-width:900px;color:#d3e5ee}.chips{display:flex;flex-wrap:wrap;gap:10px}.chips span{border:1px solid #48636f;border-radius:20px;padding:5px 14px;font-size:13px}main{max-width:1500px;margin:auto;padding:26px}nav{display:flex;flex-wrap:wrap;gap:8px 18px;padding:20px 0 28px}nav a{text-decoration:none;font-size:13px}a{color:#006b78}section{background:white;border:1px solid var(--line);border-radius:10px;padding:26px;margin:0 0 24px;scroll-margin-top:20px}h2{font-size:24px;margin:0 0 18px}p{max-width:1120px;margin:14px 0}table{width:100%;border-collapse:collapse;font-size:13px;line-height:1.45}th{text-align:left;background:#eaf1f5;color:#284753;font-weight:650}td,th{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}tr:nth-child(even){background:#f9fbfc}.table-wrap{overflow:auto;margin:18px 0}td:first-child{font-weight:550}.loaded-table td:nth-child(2),.loaded-table td:nth-child(5){white-space:nowrap}pre{font:12px/1.5 ui-monospace,Menlo,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f6f8;border:1px solid var(--line);padding:16px;border-radius:6px}code{font-size:13px;background:#edf3f5;padding:2px 4px}details{margin:16px 0;border-top:1px solid var(--line);padding-top:12px}summary{cursor:pointer;font-weight:600;color:#24616b}.filter{display:flex;align-items:center;gap:14px;font-size:13px;font-weight:600}input{padding:10px 14px;border:1px solid #afc5ce;border-radius:6px;width:330px;max-width:100%;font:inherit}footer{padding:20px 0;color:var(--muted);font-size:12px}button{padding:10px 16px;border:1px solid #93c0c8;border-radius:6px;background:#e6f7f7;color:#164752;font:inherit;cursor:pointer}.actions{display:flex;gap:12px;align-items:center;margin-top:22px}.actions a{color:#b8f3f3}.kpi{font-size:18px}
@media(max-width:700px){main{padding:12px}section{padding:16px}h1{font-size:34px}td,th{padding:8px}.filter{display:block}input{display:block;margin-top:8px}}
@media print{body{background:white;font-size:10pt}header{background:white!important;color:#132e3e;padding:0 0 16px;border-bottom:3px solid #007d8a}header p,header .eyebrow{color:#284753}.chips span{border-color:#cad9df}.actions,nav,.filter,#installed,.no-print{display:none!important}main{max-width:none;padding:0}section{border:0;border-radius:0;padding:14px 0;margin:0}h2{font-size:17pt;break-after:avoid}table{font-size:8pt}thead{display:table-header-group}tr{break-inside:avoid}td,th{padding:5px 6px}.table-wrap{overflow:visible}details{display:none}a{color:inherit;text-decoration:none}h1{font-size:30pt}@page{size:A4 landscape;margin:14mm}}
'''
nav='<nav aria-label="Report sections">'+''.join('<a href="#'+i+'">'+H(t)+'</a>' for i,t,b in sections)+'</nav>'
script='''document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('input',()=>{const q=input.value.toLowerCase();document.querySelectorAll('.'+input.dataset.filter+' tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q));}));window.addEventListener('beforeprint',()=>document.querySelectorAll('tr[hidden]').forEach(tr=>{tr.hidden=false;}));'''
report='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A4000TX — System Inventory — 7 October 2026</title><style>'+css+'</style></head><body><header><div class="eyebrow">Real hardware · Read-only inventory · 7 October 2026</div><h1>Amiga A4000TX</h1><p class="kpi">Hardware, processors, memory, storage, USB, operating system and component versions.</p><div class="chips"><span>68060 rev 5</span><span>2 MiB Chip + 624 MiB Fast</span><span>AGA + ZZ9000</span><span>XACP / ARM Core1</span><span>10.0.0.40</span></div><div class="actions"><button onclick="window.print()">Print / Save as PDF</button><a href="A4000TX-System-Report.pdf">PDF report</a><a href="installed-component-versions.csv">Component inventory CSV</a></div></header><main>'+nav+''.join(b for i,t,b in sections)+'<footer>Generated '+H(now)+' · Live evidence, owner information and prior test records are distinguished throughout.</footer></main><script>'+script+'</script></body></html>'
(R/'A4000TX-System-Report.html').write_text(report,encoding='utf-8')
